   505  void CoapBase::ProcessReceivedResponse(Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   506  {
   507      CoapMetadata coapMetadata;
   508      Message *    request = NULL;
   509      otError      error   = OT_ERROR_NONE;
   510
   511      request = FindRelatedRequest(aMessage, aMessageInfo, coapMetadata);
   512
   513      if (request == NULL)
   514      {
   515          ExitNow();
   516      }
   517
   518      switch (aMessage.GetType())
   519      {
   520      case OT_COAP_TYPE_RESET:
   521          if (aMessage.IsEmpty())
   522          {
   523              FinalizeCoapTransaction(*request, coapMetadata, NULL, NULL, OT_ERROR_ABORT);
   524          }
   525
   526          // Silently ignore non-empty reset messages (RFC 7252, p. 4.2).
   527          break;
   528
   529      case OT_COAP_TYPE_ACKNOWLEDGMENT:
   530          if (aMessage.IsEmpty())
   531          {
   532              // Empty acknowledgment.
   533              if (coapMetadata.mConfirmable)
   534              {
   535                  coapMetadata.mAcknowledged = true;
   536                  coapMetadata.UpdateIn(*request);
   537              }
   538
   539              // Remove the message if response is not expected, otherwise await response.
   540              if (coapMetadata.mResponseHandler == NULL)
   541              {
   542                  DequeueMessage(*request);
   543              }
   544          }
   545          else if (aMessage.IsResponse() && aMessage.IsTokenEqual(*request))
   546          {
   547              // Piggybacked response.
   548              FinalizeCoapTransaction(*request, coapMetadata, &aMessage, &aMessageInfo, OT_ERROR_NONE);
   549          }
   550
   551          // Silently ignore acknowledgments carrying requests (RFC 7252, p. 4.2)
   552          // or with no token match (RFC 7252, p. 5.3.2)
   553          break;
   554
   555      case OT_COAP_TYPE_CONFIRMABLE:
   556          // Send empty ACK if it is a CON message.
   557          SendAck(aMessage, aMessageInfo);
   558          FinalizeCoapTransaction(*request, coapMetadata, &aMessage, &aMessageInfo, OT_ERROR_NONE);
   559          break;
   560
   561      case OT_COAP_TYPE_NON_CONFIRMABLE:
   562          // Separate response.
   563
   564          if (coapMetadata.mDestinationAddress.IsMulticast() && coapMetadata.mResponseHandler != NULL)
   565          {
   566              // If multicast non-confirmable request, allow multiple responses
   567              coapMetadata.mResponseHandler(coapMetadata.mResponseContext, &aMessage, &aMessageInfo, OT_ERROR_NONE);
   568          }
   569          else
   570          {
   571              FinalizeCoapTransaction(*request, coapMetadata, &aMessage, &aMessageInfo, OT_ERROR_NONE);
   572          }
   573
   574          break;
   575      }
   576
   577  exit:
   578
   579      if (error == OT_ERROR_NONE && request == NULL)
   580      {
   581          if (aMessage.IsConfirmable() || aMessage.IsNonConfirmable())
   582          {
   583              // Successfully parsed a header but no matching request was found - reject the message by sending reset.
   584              SendReset(aMessage, aMessageInfo);
   585          }
   586      }
   587  }
