   597      {
   598          SuccessOrExit(error = mInterceptor(aMessage, aMessageInfo, mContext));
   599      }
   600
   601      switch (mResponsesQueue.GetMatchedResponseCopy(aMessage, aMessageInfo, &cachedResponse))
   602      {
   603      case OT_ERROR_NONE:
   604          cachedResponse->Finish();
   605          error = Send(*cachedResponse, aMessageInfo);
   606          // fall through
   607          ;
   608
   609      case OT_ERROR_NO_BUFS:
   610          ExitNow();
   611
   612      case OT_ERROR_NOT_FOUND:
   613      default:
   614          break;
   615      }
   616
   617      for (const otCoapOption *option = aMessage.GetFirstOption(); option != NULL; option = aMessage.GetNextOption())
   618      {
   619          switch (option->mNumber)
   620          {
   621          case OT_COAP_OPTION_URI_PATH:
   622              if (curUriPath != uriPath)
   623              {
   624                  *curUriPath++ = '/';
