   632
   633          default:
   634              break;
   635          }
   636      }
   637
   638      curUriPath[0] = '\0';
   639
   640      for (const Resource *resource = mResources; resource; resource = resource->GetNext())
   641      {
   642          if (strcmp(resource->mUriPath, uriPath) == 0)
   643          {
   644              resource->HandleRequest(aMessage, aMessageInfo);
   645              error = OT_ERROR_NONE;
   646              ExitNow();
   647          }
   648      }
   649
   650      if (mDefaultHandler)
   330                        mUdpForwarderContext);
   331          // message is consumed by the callback
   332      }
   333      else
   334  #endif
   335      {
   336          UdpHeader udpHeader;
   337
   338          udpHeader.SetSourcePort(aMessageInfo.mSockPort);
   339          udpHeader.SetDestinationPort(aMessageInfo.mPeerPort);
   340          udpHeader.SetLength(sizeof(udpHeader) + aMessage.GetLength());
   341          udpHeader.SetChecksum(0);
   342
   343          SuccessOrExit(error = aMessage.Prepend(&udpHeader, sizeof(udpHeader)));
