   353  otError Udp::HandleMessage(Message &aMessage, MessageInfo &aMessageInfo)
   354  {
   355      otError   error = OT_ERROR_NONE;
   356      UdpHeader udpHeader;
   357      uint16_t  payloadLength;
   358      uint16_t  checksum;
   359
   360      payloadLength = aMessage.GetLength() - aMessage.GetOffset();
   361
   362      // check length
   363      VerifyOrExit(payloadLength >= sizeof(UdpHeader), error = OT_ERROR_PARSE);
   364
   365      // verify checksum
   366      checksum = Ip6::ComputePseudoheaderChecksum(aMessageInfo.GetPeerAddr(), aMessageInfo.GetSockAddr(), payloadLength,
   367                                                  kProtoUdp);
   368      checksum = aMessage.UpdateChecksum(checksum, aMessage.GetOffset(), payloadLength);
   369
   370  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
   371      VerifyOrExit(checksum == 0xffff, error = OT_ERROR_DROP);
   372  #endif
   373
   374      VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(udpHeader), &udpHeader) == sizeof(udpHeader),
   375                   error = OT_ERROR_PARSE);
   376      aMessage.MoveOffset(sizeof(udpHeader));
   377      aMessageInfo.mPeerPort = udpHeader.GetSourcePort();
   378      aMessageInfo.mSockPort = udpHeader.GetDestinationPort();
   379
   380  #if OPENTHREAD_CONFIG_PLATFORM_UDP_ENABLE
   381      VerifyOrExit(IsMle(GetInstance(), aMessageInfo.mSockPort));
   382  #endif
   383
   384      for (UdpReceiver *receiver = mReceivers; receiver; receiver = receiver->GetNext())
   385      {
   386          VerifyOrExit(!receiver->HandleMessage(aMessage, aMessageInfo));
   387      }
   388
   389      HandlePayload(aMessage, aMessageInfo);
   390
   391  exit:
   392      return error;
   393  }
