  1012              (!aMessageInfo.GetSockAddr().IsRoutingLocator() && !aMessageInfo.GetSockAddr().IsAnycastRoutingLocator()) ||
  1013                  aMessageInfo.GetSockAddr().IsAnycastServiceLocator(),
  1014              error = OT_ERROR_NO_ROUTE);
  1015
  1016          switch (aIpProto)
  1017          {
  1018          case kProtoIcmp6:
  1019              if (mIcmp.ShouldHandleEchoRequest(aMessageInfo))
  1020              {
  1021                  IcmpHeader icmp;
  1022                  aMessage.Read(aMessage.GetOffset(), sizeof(icmp), &icmp);
  1023
  1024                  // do not pass ICMP Echo Request messages
  1025                  VerifyOrExit(icmp.GetType() != IcmpHeader::kTypeEchoRequest, error = OT_ERROR_DROP);
  1026              }
  1027
  1028              break;
  1029
  1030          case kProtoUdp:
  1031          {
  1032              UdpHeader udp;
  1033              aMessage.Read(aMessage.GetOffset(), sizeof(udp), &udp);
  1034
  1035              switch (udp.GetDestinationPort())
  1036              {
  1037              case Mle::kUdpPort:
  1038
  1039                  // do not pass MLE messages
  1040                  if (aMessageInfo.GetSockAddr().IsLinkLocal() || aMessageInfo.GetSockAddr().IsLinkLocalMulticast())
  1041                  {
  1042                      ExitNow(error = OT_ERROR_NO_ROUTE);
  1043                  }
  1044
  1045                  break;
  1046
  1047  #if OPENTHREAD_CONFIG_PLATFORM_UDP_ENABLE == 0
  1048              case kCoapUdpPort:
  1049
  1050                  // do not pass TMF messages
  1051                  if (Get<ThreadNetif>().IsTmfMessage(aMessageInfo))
