  1055
  1056                  break;
  1057  #endif // OPENTHREAD_CONFIG_PLATFORM_UDP_ENABLE
  1058
  1059              default:
  1060  #if OPENTHREAD_FTD
  1061                  if (udp.GetDestinationPort() == Get<MeshCoP::JoinerRouter>().GetJoinerUdpPort())
