   703  otError Ip6::HandleFragment(Message &aMessage, Netif *aNetif, MessageInfo &aMessageInfo, bool aFromNcpHost)
   704  {
   705      otError        error = OT_ERROR_NONE;
   706      Header         header, headerBuffer;
   707      FragmentHeader fragmentHeader;
   708      Message *      message         = NULL;
   709      uint16_t       offset          = 0;
   710      uint16_t       payloadFragment = 0;
   711      int            assertValue     = 0;
   712      bool           isFragmented    = true;
   713
   714      VerifyOrExit(aMessage.Read(0, sizeof(header), &header) == sizeof(header), error = OT_ERROR_PARSE);
   715
   716      VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(fragmentHeader), &fragmentHeader) == sizeof(fragmentHeader),
   717                   error = OT_ERROR_PARSE);
   718
   719      if (fragmentHeader.GetOffset() == 0 && !fragmentHeader.IsMoreFlagSet())
   720      {
   721          isFragmented = false;
   722          error        = aMessage.MoveOffset(sizeof(fragmentHeader));
   723
   724          ExitNow();
   725      }
   726
   727      for (message = mReassemblyList.GetHead(); message; message = message->GetNext())
   728      {
   729          VerifyOrExit(aMessage.Read(0, sizeof(headerBuffer), &headerBuffer) == sizeof(headerBuffer),
   730                       error = OT_ERROR_PARSE);
   731          if (message->GetDatagramTag() == fragmentHeader.GetIdentification() &&
   732              headerBuffer.GetSource() == header.GetSource() && headerBuffer.GetDestination() == header.GetDestination())
   733          {
   734              break;
   735          }
   736      }
   737
   738      offset          = FragmentHeader::FragmentOffsetToBytes(fragmentHeader.GetOffset());
   739      payloadFragment = aMessage.GetLength() - aMessage.GetOffset() - sizeof(fragmentHeader);
   740
   741      if (message == NULL)
   742      {
   743          VerifyOrExit((message = NewMessage(0)) != NULL, error = OT_ERROR_NO_BUFS);
   744          SuccessOrExit(error = message->SetLength(aMessage.GetOffset()));
   745
   746          message->SetTimeout(kIp6ReassemblyTimeout);
   747          SuccessOrExit(error = message->SetOffset(0));
   748          message->SetDatagramTag(fragmentHeader.GetIdentification());
   749
   750          // copying the non-fragmentable header to the fragmentation buffer
   751          assertValue = aMessage.CopyTo(0, 0, aMessage.GetOffset(), *message);
   752          assert(assertValue == aMessage.GetOffset());
   753
   754          if (!mTimer.IsRunning())
   755          {
   756              mTimer.Start(kStateUpdatePeriod);
   757          }
   758
   759          mReassemblyList.Enqueue(*message);
   760
   761          otLogDebgIp6("start reassembly.");
   762      }
   763
   764      otLogInfoIp6("Fragment with id %d received > %d bytes, offset %d", message->GetDatagramTag(), payloadFragment,
   765                   offset);
   766
   767      if (offset + payloadFragment + aMessage.GetOffset() > kMaxAssembledDatagramLength)
   768      {
   769          otLogWarnIp6("Package too large for fragment buffer");
   770          ExitNow(error = OT_ERROR_NO_BUFS);
   771      }
   772
   773      // increase message buffer if necessary
   774      if (message->GetLength() < offset + payloadFragment + aMessage.GetOffset())
   775      {
   776          SuccessOrExit(error = message->SetLength(offset + payloadFragment + aMessage.GetOffset()));
   777      }
   778
   779      // copy the fragment payload into the message buffer
   780      assertValue = aMessage.CopyTo(aMessage.GetOffset() + sizeof(fragmentHeader), aMessage.GetOffset() + offset,
   781                                    payloadFragment, *message);
   782      assert(assertValue == static_cast<int>(payloadFragment));
   783
   784      // check if it is the last frame
   785      if (!fragmentHeader.IsMoreFlagSet())
   786      {
   787          // use the offset value for the whole ip message length
   788          SuccessOrExit(error = message->SetOffset(offset + payloadFragment + aMessage.GetOffset()));
   789      }
   790
   791      if (message->GetOffset() >= message->GetLength())
   792      {
   793          // creates the header for the reassembled ipv6 package
   794          VerifyOrExit(aMessage.Read(0, sizeof(header), &header) == sizeof(header), error = OT_ERROR_PARSE);
   795          header.SetPayloadLength(message->GetLength() - sizeof(header));
   796          header.SetNextHeader(static_cast<IpProto>(fragmentHeader.GetNextHeader()));
   797          assertValue = message->Write(0, sizeof(header), &header);
   798          assert(assertValue == sizeof(header));
   799
   800          otLogDebgIp6("Reassembly complete.");
   801
   802          mReassemblyList.Dequeue(*message);
   803
   804          error = HandleDatagram(*message, aNetif, aMessageInfo.mLinkInfo, aFromNcpHost);
   805      }
   806
   807  exit:
   808      if (error != OT_ERROR_DROP && error != OT_ERROR_NONE && isFragmented)
   809      {
   810          if (message != NULL)
   811          {
   812              mReassemblyList.Dequeue(*message);
   813              message->Free();
   814          }
   815          otLogWarnIp6("Reassembly failed: %s", otThreadErrorToString(error));
   816      }
   817      if (isFragmented)
   818      {
   819          // drop all fragments, the payload is stored in the fragment buffer
   820          error = OT_ERROR_DROP;
   821      }
   822
   823      return error;
   824  }
